<script setup>import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { projects } from '../data/projects.js'; const route = useRoute(); const project = computed(() => projects.find(p => p.slug === route.params.slug))</script><template><article v-if="project" class="project-detail"><RouterLink to="/" class="back-link">← Tilbage til projekter</RouterLink><p class="eyebrow">{{ project.category }}</p><h1>{{ project.title }}</h1><p>{{ project.description }}</p><img v-if="project.image" :src="project.image" :alt="project.imageAlt || ''"/></article><section v-else class="project-detail"><h1>Projektet blev ikke fundet</h1><RouterLink to="/">← Tilbage til forsiden</RouterLink></section></template>
